      r'\bnew to (?:praying|prayer|salah|namaz)\b',
      r'\b(?:fajr|dhuhr|zuhr|asr|maghrib|isha) (?:prayer |salah |namaz )?step by step\b',
      r'\bstep by step\b.*\b(?:fajr|dhuhr|zuhr|asr|maghrib|isha|salah|namaz|prayer)\b',
