      r'\bhow to wash for prayer\b',
      r'\bperform (?:the )?wudu\b',
      r'^wudu$',
      r'\bhow to do ablution\b',
      r'\b(?:wuzu|wudu|wudhu|wuzoo|wazu|wudoo) (?:kaise|ka tarika|karne ka tarika|karte)\b',
      r'\bhow (?:to|do i|do you) (?:do |make |perform )?(?:wuzu|wudhu|wazu|wudoo|ablution)\b',
