      r'\bmarry without (?:my )?(?:parents?|family|wali|father)\b',
      r'\bwalima\b',
      r'\bis (?:marriage|nikah) (?:compulsory|obligatory|fard|sunnah|required|mandatory)\b',
      r'\bwhy (?:should|do) (?:i|muslims?) (?:get )?marr(?:y|ied)\b',
