      r'\bdiscipline (?:my )?(?:kids?|children|child)\b',
      r'\bhit(?:ting)? (?:my |a )?(?:kids?|children|child)\b',
      r'\bbeat(?:ing)? (?:my |a )?(?:kids?|children|child)\b',
