  CoreEntry(
    id: 'ibrahim-sacrifice',
    patterns: <String>[
      r'\bibrahim\b.*\b(?:sacrific\w*|son|ismail|ishmael|isaac|dream|knife)\b',
      r'\babraham\b.*\b(?:sacrific\w*|son|ishmael|isaac|dream|knife)\b',
